import {lessons,units,STORAGE_KEY,sanitizeProgress,nextLesson,canOpen,totalXP,complete,holeId,terminals,circuitState,makeSketch,net,buttonState,inputLevel,bounceSignal,countPresses,debounce,caught,makeTimerSketch,makeDebounceSketch} from './model.mjs';
const $=s=>document.querySelector(s);const app=$('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true,p;
try{p=sanitizeProgress(JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}'));}catch{p=sanitizeProgress({});storageOK=false;}
let view='home',lesson=null,selected=null,checked=false,hint=false,lab={parts:[],wires:[]},chosenPart=null,selectedPin=null,running=false,started=0,delay=500,labPassed=false,toastTimer,cursor='0,0',pullup=true,pressed=false,pressCycle=0,serialLines=[],lastSerial=0,reading=1,bs={},nw={};
const pinName=id=>{const fixed={gpio:'GPIO 23',gpio22:'GPIO 22',gnd:'GND',vcc:'3V3'}[id];if(fixed)return fixed;const [h,r]=id.split(':');const c=Number(h.slice(1))+1;return r===undefined?`${c}. sütun (${h[0]==='t'?'a–e':'f–j'})`:String.fromCharCode(97+Number(r))+c;};
const icon=(name)=>{const shapes={path:'<path d="M4 17h6V7h10M4 7h3m10 10h3"/><circle cx="4" cy="17" r="2"/><circle cx="20" cy="7" r="2"/>',lab:'<path d="M8 3h8M10 3v7l-6 10h16l-6-10V3M7 15h10"/>',book:'<path d="M5 3h14v18H5zM9 3v18M12 8h4m-4 4h4"/>',led:'<path d="M8 15V8a4 4 0 0 1 8 0v7M6 15h12M9 15v7m6-7v5M2 4l3 2m14 0 3-2M12 0v2"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',check:'<path d="m5 12 5 5L20 7"/>',lock:'<rect x="6" y="10" width="12" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',button:'<rect x="5" y="5" width="14" height="14" rx="2"/><circle cx="12" cy="12" r="4"/><path d="M2 8h3m-3 8h3m14-8h3m-3 8h3"/>',resistor:'<path d="M12 0v5m0 14v5"/><rect x="7" y="5" width="10" height="14" rx="3"/><path d="M7 9h10M7 15h10"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.chip}</svg>`;};
const brand=()=>`<a class="brand" href="#/" data-home aria-label="Pin by Pin Lab ana sayfa"><svg viewBox="0 0 40 46" fill="none" aria-hidden="true"><rect x="6" y="7" width="28" height="32" rx="5" stroke="currentColor" stroke-width="1.5"/><path d="M13 31V15h8a6 6 0 0 1 0 12h-8M3 15h3m-3 8h3m-3 8h3m28-16h3m-3 8h3m-3 8h3M15 4v3m10-3v3m-10 32v3m10-3v3" stroke="currentColor" stroke-width="1.5"/></svg><span>pin by pin<small>LEARNING LAB</small></span></a>`;
function art(){return `<svg viewBox="0 0 450 300" fill="none" role="img" aria-label="GPIO 23 üzerinden direnç ve kırmızı LED’e uzanan bir devre çizimi"><path d="M50 175h99v-60h109" stroke="#b2b9a4" stroke-width="1.5" stroke-dasharray="4 5"/><path d="M184 230h152V125" stroke="#a6ad9b" stroke-width="1.5"/><rect x="47" y="106" width="112" height="147" rx="7" fill="#294139"/><rect x="64" y="122" width="78" height="65" rx="3" fill="#b9c0af"/><path d="M73 139h11v-9h12v14h13v-14h12v9h12" stroke="#294139" stroke-width="3"/><text x="103" y="174" text-anchor="middle" fill="#294139" font-size="9" font-family="monospace">ESP32</text><rect x="86" y="230" width="35" height="28" rx="3" fill="#9fa79a"/>${Array.from({length:10},(_,i)=>`<path d="M41 ${121+i*12}h6m112 0h6" stroke="#b69454" stroke-width="4"/>`).join('')}<circle cx="130" cy="207" r="4" fill="#e5f292"/><path d="M165 153h36v-38h29m51 0h20" stroke="#ca5935" stroke-width="3"/><rect x="230" y="106" width="50" height="18" rx="6" fill="#d7c69e" stroke="#9f8c60"/><path d="M240 107v16m8-16v16m17-16v16" stroke="#a4513b" stroke-width="3"/><path d="M307 116V88a14 14 0 0 1 28 0v28m-29 1h31m-28 0v24m24-24v13" stroke="#ca5935" stroke-width="2"/><path d="M308 114V88a13 13 0 0 1 26 0v26z" fill="#df7856"/><path d="M314 86v14" stroke="#fbd7b6" stroke-width="3"/><path d="M320 52v-8m24 18 7-7m-55 7-7-7m65 33h8" stroke="#c4b36b" stroke-width="1.5"/><circle cx="320" cy="97" r="39" stroke="#ccc9ae" stroke-dasharray="2 5"/><text x="225" y="91" fill="#7d8475" font-size="10" font-family="monospace">220 Ω</text><path d="M290 176h58" stroke="#b6bdac"/><text x="290" y="193" fill="#7d8475" font-size="9" font-family="monospace">İLK IŞIK.</text><text x="290" y="208" fill="#7d8475" font-size="9" font-family="monospace">SENİN ESERİN.</text><text x="176" y="149" fill="#7d8475" font-size="8" font-family="monospace">23</text><text x="177" y="245" fill="#7d8475" font-size="8" font-family="monospace">GND</text><path d="M26 73h10m-5-5v10M386 241h10m-5-5v10" stroke="#adb49f"/></svg>`;}
function announce(text){$('#announcer').textContent=text;}
function toast(text){document.querySelector('.toast')?.remove();clearTimeout(toastTimer);const d=document.createElement('div');d.className='toast';d.textContent=text;d.setAttribute('role','status');document.body.append(d);toastTimer=setTimeout(()=>d.remove(),4000);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(p));}catch{storageOK=false;toast('Kayıt yapılamadı. Defterim’den ilerlemeni indirebilirsin.');}}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function shell(content){return `<div class="shell"><aside class="sidebar">${brand()}<nav class="nav" aria-label="Ana menü">${[['home','path','Öğrenme yolu'],['workshop','lab','Atölye'],['notebook','book','Defterim']].map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''} title="${t}" aria-label="${t}">${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="free">Herkes için ücretsiz.</div><p>Bir kitin olmasa da<br>bir başlangıcın olsun.</p><a href="https://github.com/emjnbulut/esp32-from-zero" target="_blank" rel="noopener">ESP32 From Zero ↗</a></div></aside><main id="main" class="main"><header class="topbar"><div class="crumb">ATÖLYE / <strong>ESP32</strong></div><div class="stats"><span class="stat-star">✳ <b>${totalXP(p)}</b> XP</span><span><b>${p.completed.length}</b> / ${lessons.length} görev</span><span class="avatar" title="İlerleme bu cihazda">01</span></div></header>${!storageOK?'<div class="storage-warning">Tarayıcı kaydı kullanılamıyor. İlerlemeni Defterim’den dosya olarak indirebilirsin.</div>':''}${content}<footer class="footer"><span>PIN BY PIN LAB · Birlikte, adım adım.</span><span>ESP32 From Zero müfredatından · Sürüm 0.3</span></footer></main></div>`;}
function home(){const next=nextLesson(p);return shell(`<section class="hero"><div class="hero-copy"><div class="eyebrow">MERAK ET. BAĞLA. ÇALIŞTIR.</div><h1>Bir pinle<br><em>başlar.</em></h1><p>Kitin olmasa da olur. Küçük adımlarla devreni kur, koduna hayat ver. İlk ışığını birlikte yakalım.</p></div><div class="hero-art">${art()}<span class="hero-note">ÇİZİM 001 / İLK DEVRE</span></div></section><div class="dashboard"><section aria-label="Öğrenme yolu"><div class="section-label"><strong>ÖĞRENME YOLUN</strong><span>01 · ESP32 TEMELLERİ</span></div>${units.filter(u=>u.available).map(u=>{const ls=lessons.filter(l=>l.unit===u.id),count=ls.filter(l=>p.completed.includes(l.id)).length;return `<article class="unit ${next?.unit===u.id?'current':''}"><div class="unit-head"><span class="unit-num">0${u.id}</span><div><h3>${u.title}</h3><p>${u.subtitle}</p></div><span class="unit-status">${count===ls.length?'TAMAMLANDI':`${count} / ${ls.length}`}</span></div><div class="path">${ls.map((l,i)=>{const done=p.completed.includes(l.id),open=canOpen(l.id,p),active=next?.id===l.id;return `<button class="lesson-node ${done?'done':''} ${active?'next':''}" data-lesson="${l.id}" ${open?'':'disabled'} aria-label="${esc(l.title)}${done?', tamamlandı':!open?', önceki görevleri tamamla':''}">${active?'<span class="next-label">SIRADAKİ ADIM</span>':''}<span class="node-icon">${icon(done?'check':!open?'lock':l.type==='lab'?'led':i===0?'chip':i===1?'book':'lab')}</span><span class="node-title">${l.title}</span><span class="node-meta">${l.minutes} DK · ${l.xp} XP</span></button>`;}).join('')}</div></article>`;}).join('')}<div class="section-label"><strong>YOLUN DEVAMINDA</strong><span>MÜFREDAT · HAZIRLANIYOR</span></div>${units.filter(u=>!u.available).map(u=>`<div class="upcoming"><span class="unit-num">${String(u.id).padStart(2,'0')}</span><div><h3>${u.title}</h3><p>${u.subtitle}</p></div><span>HAZIRLANIYOR</span></div>`).join('')}</section><aside><div class="continue-card"><div class="eyebrow">${p.completed.length?'KALDIĞIN YERDEN':'İLK ADIMIN HAZIR'}</div><h2>${next?next.title:'İlk ışığın yandı.'}</h2><p>${next?'Birkaç dakika, yeni bir keşif. İlerlemek için bir kite ihtiyacın yok.':'Açık olan tüm görevleri tamamladın. Atölyede farklı bağlantılar deneyebilirsin.'}</p><button class="primary" ${next?`data-lesson="${next.id}"`:'data-nav="workshop"'}>${p.completed.length?'Devam et':'Öğrenmeye başla'} <span>→</span></button></div><div class="note-card"><div class="eyebrow">ATÖLYE DEFTERİ / 001</div><h3>Yanlış bağlamak da öğrenmektir.</h3><p>Burada hata yapabilirsin. Bir kabloyu değiştir, tekrar dene. Her bağlantı sana bir şey anlatır.</p></div><div class="note-card"><div class="eyebrow">KÜÇÜK ADIMLAR BİRİKİR</div><div class="tiny-progress"><div style="width:${p.completed.length/lessons.length*100}%"></div></div><div class="progress-caption"><span>${p.completed.length} görev tamamlandı</span><span>${lessons.length} GÖREV</span></div><p style="margin-top:14px">İlerlemen bu tarayıcıda saklanır.<br>Defterim’den bir kopya alabilirsin.</p></div></aside></div>`);}
function notebook(){return shell(`<section class="notebook"><div class="eyebrow">KİŞİSEL ATÖLYE DEFTERİN</div><h1 style="margin-top:18px">Öğrendiklerin burada.</h1><p>${p.completed.length} görev · ${totalXP(p)} XP · ${p.dates.length} farklı günde çalıştın.<br>Bu kayıt yalnızca bu tarayıcıda tutulur. Cihaz değiştirmeden önce bir kopya indir.</p>${p.completed.length?lessons.filter(l=>p.completed.includes(l.id)).map(l=>`<div class="record"><div><strong>${l.title}</strong><br><small>ÜNİTE ${l.unit} · ${l.xp} XP</small></div><button class="secondary" data-lesson="${l.id}">Tekrar et ↗</button></div>`).join(''):'<div class="empty-note">Henüz bir kayıt yok. İlk görevin hazır.<br><button class="primary" style="margin-top:18px" data-lesson="board">İlk adıma git ↗</button></div>'}<div class="notebook-actions"><button class="secondary" id="export-progress">Defteri indir ↓</button><button class="secondary" id="import-progress">Defter yükle ↑</button><button class="secondary" id="reset-progress">İlerlemeyi sıfırla</button><input class="sr-only" type="file" id="progress-file" accept="application/json,.json" aria-label="İlerleme dosyası"></div></section>`);}
function lessonPage(){const index=lessons.findIndex(l=>l.id===lesson.id);return `<div class="lesson-shell"><header class="lesson-header"><button class="close" data-nav="home" aria-label="Öğrenme yoluna dön">×</button><span class="mono">ÜNİTE 0${lesson.unit}</span><div class="lesson-progress" role="progressbar" aria-label="Görev sırası" aria-valuenow="${index+1}" aria-valuemin="0" aria-valuemax="${lessons.length}"><i style="width:${(index+1)/lessons.length*100}%"></i></div><span class="mono">${lesson.minutes} DK · ${lesson.xp} XP</span></header><main id="main" class="lesson-layout"><aside class="lesson-copy"><div class="eyebrow">${lesson.tag} / ${String(index+1).padStart(2,'0')}</div><h1 class="focus-title" tabindex="-1">${lesson.title}</h1><p>${lesson.intro}</p><button class="secondary hint-button" id="hint" aria-expanded="${hint}">Küçük bir ipucu ${hint?'−':'+'}</button><p class="hint-text" id="hint-text" ${hint?'':'hidden'}>${lesson.hint}</p><div class="source">BU DERSİN KAYNAĞI<br><a target="_blank" rel="noopener" href="https://github.com/emjnbulut/esp32-from-zero/tree/main/lessons/${units.find(u=>u.id===lesson.unit).source}">ESP32 From Zero · Bölüm ${lesson.unit} ↗</a></div></aside>${lesson.type==='quiz'?quiz():lesson.type==='bounce'?bouncePage():lesson.type==='nowait'?nowaitPage():labPage(false)}</main></div>`;}
function quiz(){const offset=lessons.indexOf(lesson)%3;const order=[0,1,2].map(i=>(i+offset)%3);return `<section class="exercise quiz">${lesson.code?`<div class="code-label">SKETCH.INO / OKU VE TAHMİN ET</div><pre><code>${esc(lesson.code)}</code></pre>`:`<div class="quiz-illustration">${lesson.id==='rows'?breadboardMini():art()}</div>`}<h2>${lesson.question}</h2><div class="choices" role="group" aria-label="Yanıt seçenekleri">${order.map((n,i)=>`<button class="choice ${selected===n?'selected':''} ${checked&&n===lesson.answer?'correct':''}" data-choice="${n}" ${checked?'disabled':''} aria-pressed="${selected===n}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${lesson.choices[n]}</span></button>`).join('')}</div><div class="feedback ${checked?'good':''}" id="feedback" role="status">${checked?lesson.explanation:''}</div><div class="exercise-bottom"><small>Denemek serbest. Her zaman.</small><button class="primary" id="check-answer" ${selected===null?'disabled':''}>${checked?'Görevi tamamla →':'Kontrol et →'}</button></div></section>`;}
function breadboardMini(){return `<svg viewBox="0 0 260 110" aria-label="7 numaralı sütunda a ile e delikleri bağlıdır; f ayrı bir gruptadır"><rect x="10" y="4" width="240" height="102" rx="5" fill="#fffef9" stroke="#dcded1"/><path d="M130 18v46" stroke="#e5f292" stroke-width="14"/>${Array.from({length:6},(_,r)=>Array.from({length:9},(_,c)=>`<circle cx="${50+c*20}" cy="${18+r*12+(r===5?10:0)}" r="2" fill="#647564"/>`).join('')).join('')}<text x="126" y="101" font-family="monospace" font-size="10" fill="#243c35">7</text><text x="20" y="22" font-size="10">a</text><text x="20" y="70" font-size="10">e</text><text x="20" y="93" font-size="10">f</text></svg>`;}
const xy=(c,r)=>[350+c*34,r<5?158+r*14:253+(r-5)*14];
function point(id){if(id==='gpio')return [240,190];if(id==='gnd')return [240,290];if(id==='gpio22')return [240,240];if(id==='vcc')return [240,140];const [h,r]=id.split(':');return xy(Number(h.slice(1)),r!==undefined?Number(r):h[0]==='t'?2:7);}
function pin(id,x,y,label){return `<g class="pin" data-pin="${id}" data-x="${x}" data-y="${y}" tabindex="0" role="button" aria-label="${label}"><circle class="${selectedPin?.id===id?'selected-pin':''}" cx="${x}" cy="${y}" r="7" fill="#d9b86e" stroke="#65725e" stroke-width="1"/></g>`;}
function bench(){const active=running&&circuitState(lab).ok;return `<svg id="bench" viewBox="0 0 920 405" aria-label="Etkileşimli ESP32 ve breadboard. Parça seçip bir deliğe tıkla, iki deliğe sırayla tıklayarak kablo bağla."><defs><pattern id="dot-grid" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".7" fill="#cbd1c1"/></pattern></defs><rect width="920" height="405" fill="url(#dot-grid)"/><text x="40" y="39" font-size="10" font-family="monospace" fill="#7b8472">ÇALIŞMA MASASI / ESP32 · GPIO 23</text><rect x="40" y="84" width="188" height="260" rx="11" fill="#294139"/><rect x="69" y="105" width="130" height="103" rx="4" fill="#aeb9a5"/><path d="M82 130h15v-14h15v23h15v-23h15v23h15v-23h15v14h15" stroke="#53614b" stroke-width="5" fill="none"/><text x="134" y="180" text-anchor="middle" font-family="monospace" font-size="15" fill="#294139">ESP32</text><text x="134" y="196" text-anchor="middle" font-family="monospace" font-size="8" fill="#53614b">DEVKIT · WROOM</text><rect x="105" y="317" width="57" height="35" rx="3" fill="#9ca596"/><circle cx="78" cy="242" r="5" fill="${running?'#e5f292':'#6e7e61'}"/><text x="92" y="245" font-size="9" font-family="monospace" fill="#bdc8ae">PWR</text>${Array.from({length:15},(_,i)=>`<path d="M33 ${103+i*15}h7m188 0h8" stroke="#bc9a52" stroke-width="5"/>`).join('')}<path d="M228 140h12m-12 50h12m-12 50h12m-12 50h12" stroke="#bc9a52" stroke-width="3"/><g font-family="monospace" font-size="10" fill="#243c35"><text x="252" y="131">3V3</text><text x="252" y="181">23</text><text x="252" y="281">GND</text>${lesson?.mode==='button'?'<text x="252" y="231">22</text>':''}</g><rect x="319" y="99" width="565" height="258" rx="9" fill="#fffef9" stroke="#cbd2c2"/><path d="M335 232h534" stroke="#d6dacd" stroke-width="10"/><path d="M337 123h530" stroke="#cb6748"/><path d="M337 336h530" stroke="#7c9ca4"/><g font-family="monospace" font-size="9" fill="#78826f">${Array.from({length:16},(_,c)=>`<text x="${346+c*34}" y="145">${c+1}</text>`).join('')}${Array.from({length:10},(_,r)=>`<text x="328" y="${xy(0,r)[1]+3}">${String.fromCharCode(97+r)}</text>`).join('')}</g>${lab.wires.map(([a,b],i)=>{const [x1,y1]=point(a),[x2,y2]=point(b);const mid=(x1+x2)/2;return `<path class="wire" data-wire="${i}" d="M${x1} ${y1}H${mid}V${y2}H${x2}" stroke="${a==='gnd'||b==='gnd'?'#506779':a==='gpio22'||b==='gpio22'?'#d4a72c':'#c7653e'}" aria-label="Kablo ${i+1}: ${pinName(a)} ile ${pinName(b)}"/>`;}).join('')}${pin('vcc',240,140,'ESP32 3V3 sabit besleme')}${pin('gpio',240,190,'ESP32 GPIO 23')}${pin('gnd',240,290,'ESP32 GND')}${lesson?.mode==='button'?pin('gpio22',240,240,'ESP32 GPIO 22'):''}${Array.from({length:10},(_,r)=>Array.from({length:16},(_,c)=>{const [x,y]=xy(c,r);return `<g class="pin" data-hole="${c},${r}" data-pin="${holeId(c,r)}:${r}" data-x="${x}" data-y="${y}" tabindex="${cursor===`${c},${r}`?0:-1}" role="button" aria-label="Breadboard ${String.fromCharCode(97+r)}${c+1}"><circle class="hit" cx="${x}" cy="${y}" r="7"/><circle class="${selectedPin?.id===`${holeId(c,r)}:${r}`?'selected-pin':''}" cx="${x}" cy="${y}" r="4" fill="#d7dbce" stroke="#8a9580" stroke-width=".7"/></g>`;}).join('')).join('')}${lab.parts.map(part=>{const [x,y]=xy(part.col,part.row),[x2]=xy(part.col+(part.kind==='led'?1:3),part.row);if(part.kind==='button')return pushButton(part);if(part.kind==='resistor')return `<g class="part-placed" data-part="resistor" tabindex="0" role="button" aria-label="220 ohm direnç. Sürükleyerek taşı."><path pointer-events="none" d="M${x} ${y}v-26h${x2-x}v26" fill="none" stroke="#9e9e86" stroke-width="2"/><rect x="${x+25}" y="${y-34}" width="52" height="17" rx="5" fill="#d7c397" stroke="#9e8b60"/><path d="M${x+35} ${y-33}v15m8-15v15m13-15v15" stroke="#b05436" stroke-width="3"/><text x="${x+49}" y="${y-43}" text-anchor="middle" font-size="9" font-family="monospace" fill="#6e765e">220 Ω</text></g>`;return `<g class="part-placed" data-part="led" tabindex="0" role="button" aria-label="Kırmızı LED. Sürükleyerek taşı."><path pointer-events="none" d="M${x} ${y}v-25h8M${x2-8} ${y-25}h8v25" stroke="#929a87" stroke-width="2" fill="none"/><circle id="led-glow" cx="${x+17}" cy="${y-41}" r="31" fill="#e77939" opacity="${active?.13:0}"/><path id="led-bulb" d="M${x+5} ${y-25}v-21a12 12 0 0 1 24 0v21z" fill="${active?'#f57c43':'#a35640'}" stroke="#863e2e" stroke-width="1.5"/><path d="M${x+11} ${y-45}v9" stroke="#f7b692" stroke-width="2"/><path d="M${x+2} ${y-25}h30" stroke="#863e2e" stroke-width="3"/><text pointer-events="none" x="${x-5}" y="${y+16}" font-family="monospace" font-size="10" fill="#a64d2e">${part.reversed?'−':'+'}</text><text pointer-events="none" x="${x2-2}" y="${y+16}" font-family="monospace" font-size="10" fill="#6d7c69">${part.reversed?'+':'−'}</text></g>`;}).join('')}<text x="40" y="385" font-size="9" font-family="monospace" fill="#7b8472">${chosenPart?'PARÇA SEÇİLİ · Bir deliğe tıkla.':selectedPin?'KABLO BAŞLANGICI SEÇİLİ · İkinci ucu seç.':'İKİ PİN SEÇ → BİR KABLO BAĞLA'}</text></svg>`;}
function labPage(workshop){return `<section class="exercise"><div class="workbench-top"><div class="eyebrow">${workshop?'SERBEST DENEME':'DENEY / '+labNo()}</div><span class="model-tag">REHBERLİ DEVRE MODELİ</span></div><div class="lab-tools" style="margin-bottom:12px"><button class="part-button ${chosenPart==='resistor'?'selected':''}" data-add="resistor" ${lab.parts.some(p=>p.kind==='resistor')?'disabled':''}>${icon('resistor')}220 Ω direnç</button><button class="part-button ${chosenPart==='led'?'selected':''}" data-add="led" ${lab.parts.some(p=>p.kind==='led')?'disabled':''}>${icon('led')}Kırmızı LED</button>${lesson.mode==='button'?`<button class="part-button ${chosenPart==='button'?'selected':''}" data-add="button" ${lab.parts.some(p=>p.kind==='button')?'disabled':''}>${icon('button')}Buton</button>`:''}<button class="secondary" id="reverse-led" ${lab.parts.some(p=>p.kind==='led')?'':'disabled'}>LED yönünü çevir</button>${lesson.mode==='button'?`<button class="secondary" id="rotate-button" ${lab.parts.some(p=>p.kind==='button')?'':'disabled'}>Butonu döndür</button>`:''}<button class="secondary" id="clear-lab">Masayı temizle</button></div><div class="bench-frame">${bench()}<div class="bench-help">Parçayı sürükle veya seçip bir deliğe tıkla. Kablo için iki uç seç. Kaldırmak için kabloya tıkla. Klavye: ok tuşlarıyla delikler arasında gez, Enter ile seç, Escape ile iptal et.</div></div><div class="wire-list" aria-label="Kablolar">${lab.wires.map(([a,b],i)=>`<button class="wire-delete" data-wire="${i}" aria-label="${pinName(a)} ile ${pinName(b)} arasındaki kabloyu kaldır">${pinName(a)} — ${pinName(b)} ×</button>`).join('')}</div><div class="lab-lower"><div><div class="code-label">SKETCH.INO · ${lesson.mode==='steady'?'İLK ÇIKIŞ':lesson.mode==='button'?'BUTONU OKU':'İKİ BEKLEME, BİR DÖNGÜ'}</div><pre><code id="sketch">${esc(makeSketch(lesson.mode,delay,pullup))}</code></pre><button class="secondary" style="margin-top:10px" id="download-code">Arduino kodunu indir ↓</button></div><div><div class="code-label">ÇALIŞTIR VE GÖZLEMLE</div><div class="lab-control">${lesson.mode==='button'?buttonControls():lesson.mode!=='steady'?`<label for="delay">Her delay() için bekleme süresi</label><input id="delay" type="range" min="100" max="2000" step="50" value="${delay}"><div class="range-readout"><span id="delay-value">${delay} ms</span><span id="frequency">${(1000/(delay*2)).toFixed(2)} döngü/sn</span></div>`:'<p style="font-size:12px;line-height:1.8">GPIO 23, OUTPUT olarak ayarlandı.<br>HIGH → LED’e giden çıkış açık.</p>'}<button class="primary" id="run-lab">${running?'■ Durdur':'▶ Devreyi çalıştır'}</button><div class="lab-state" id="lab-state" role="status">${running?circuitState(lab).message:'Devreni kurduktan sonra çalıştır.'}</div></div><p class="model-note">Bu ders modeli bağlantı, LED yönü, 220 Ω direnç ve seçilen zamanlamayı değerlendirir. Tam ESP32 emülatörü değildir. İndirilen kod, gerçek kartta Arduino IDE ile kullanılabilir.</p></div></div>${!workshop?`<div class="feedback" id="lab-feedback" role="status"></div><div class="exercise-bottom"><small>Çalışan devreni kontrol ederek ilerle.</small><button class="primary" id="finish-lab" disabled>Görevi tamamla ↗</button></div>`:''}</section>`;}
function focusKey(el){if(!el||el===document.body||!app.contains(el))return null;if(el.id)return '#'+el.id;for(const a of ['data-pin','data-choice','data-add','data-part','data-wire','data-version','data-lesson','data-nav'])if(el.hasAttribute(a))return `[${a}="${el.getAttribute(a)}"]`;return null;}
function render(focus=false){const key=focus?null:focusKey(document.activeElement);app.innerHTML=view==='home'?home():view==='notebook'?notebook():view==='lesson'?lessonPage():shell(`<section class="notebook" style="padding-bottom:20px"><div class="eyebrow">SERBEST ATÖLYE</div><h1 style="margin-top:18px">Bir bağlantıyı değiştir.</h1><p>İlk LED devresiyle denemeler yap. Bu alan ilerleme puanı vermez; merak etmek için her zaman açık.</p></section><div class="workshop">${labPage(true)}</div>`);bind();if(focus){window.scrollTo(0,0);document.querySelector('.focus-title')?.focus();}else if(key)document.querySelector(key)?.focus({preventScroll:true});}
const routes={home:'#/',workshop:'#/atolye',notebook:'#/defter'};
function go(hash){if(location.hash===hash)route();else location.hash=hash;}
function route(){const m=location.hash.match(/^#\/ders\/([\w-]+)$/);if(m){if(canOpen(m[1],p)){start(m[1]);return;}history.replaceState(null,'','#/');}show(Object.keys(routes).find(k=>routes[k]===location.hash)||'home');}
function navigate(v){go(routes[v]||'#/');}
function openLesson(id){go('#/ders/'+id);}
function show(v){running=false;view=v;selectedPin=null;chosenPart=null;if(v==='workshop'){lesson={mode:'blink'};lab={parts:[],wires:[]};delay=500;}render(true);}
function start(id){lesson=lessons.find(l=>l.id===id);view='lesson';selected=null;checked=false;hint=false;labPassed=false;running=false;chosenPart=null;selectedPin=null;delay=500;pullup=true;pressed=false;pressCycle=0;serialLines=[];bs={ms:0,streak:0,signal:null,count:0};nw={mode:'delay',t0:performance.now(),presses:[],downAt:null,blinking:true,streak:0,triedDelay:0};lab=lesson.mode==='button'?{parts:[{kind:'resistor',col:3,row:0},{kind:'led',col:6,row:0}],wires:[['gpio','t3:2'],['t7:2','gnd']]}:{parts:[],wires:[]};render(true);}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function finish(){const already=p.completed.includes(lesson.id);p=complete(p,lesson.id,today());save();running=false;const next=nextLesson(p);app.innerHTML=`<main id="main" class="success"><div class="success-mark">✓</div><div class="eyebrow" style="margin-top:25px">BİR ADIM DAHA ATTIN</div><h1>${({light:'İlk ışığın yandı.',challenge:'Ritmi sen belirledin.',button:'Kart seni duydu.',bounce:'Her basış bir kez.',nowait:'Aynı anda iki iş.'})[lesson.id]||'Artık bunu biliyorsun.'}</h1><p>${esc(lesson.title)} görevini tamamladın.<br>${lesson.type==='quiz'?esc(lesson.explanation):'Bağlantın ve programının davranışı bu dersin hedefini karşılıyor.'}</p><div class="earned">${already?'TEKRAR TAMAMLANDI · XP ZATEN KAZANILMIŞTI':`+${lesson.xp} XP`} &nbsp; / &nbsp; ${p.completed.length} / ${lessons.length} GÖREV</div><div class="success-actions"><button class="secondary" data-nav="home">Öğrenme yoluna dön</button>${next?`<button class="primary" data-lesson="${next.id}">Sıradaki adım ↗</button>`:'<button class="primary" data-nav="workshop">Atölyede keşfet ↗</button>'}</div></main>`;bind();window.scrollTo(0,0);announce('Görev tamamlandı.');}
function invalidate(){running=false;labPassed=false;selectedPin=null;}
function place(kind,col,row){const max=kind==='resistor'?12:kind==='button'?13:14;col=Math.max(0,Math.min(max,col));row=kind==='button'?4:Math.max(0,Math.min(9,row));lab.parts=lab.parts.filter(x=>x.kind!==kind);lab.parts.push({kind,col,row,reversed:false});chosenPart=null;invalidate();render();announce(`${{led:'LED',resistor:'Direnç',button:'Buton'}[kind]} yerleştirildi.`);}
function connect(el){if(running){toast('Bağlantı değiştirmek için önce devreyi durdur.');return;}const id=el.dataset.pin;if(chosenPart){if(el.dataset.hole){const [c,r]=el.dataset.hole.split(',').map(Number);place(chosenPart,c,r);}else toast('Parçayı breadboard üzerindeki bir deliğe yerleştir.');return;}if(!selectedPin){selectedPin={id};render();announce('İlk uç seçildi. İkinci ucu seç.');return;}const a=selectedPin.id;selectedPin=null;if(net(a)!==net(id)&&!lab.wires.some(([x,y])=>(net(x)===net(a)&&net(y)===net(id))||(net(x)===net(id)&&net(y)===net(a))))lab.wires.push([a,id]);invalidate();render();}
function drag(element,kind){element.addEventListener('pointerdown',e=>{if(e.button!==0||running)return;const x=e.clientX,y=e.clientY;let ghost=null,moved=false;const move=ev=>{if(Math.hypot(ev.clientX-x,ev.clientY-y)<7&&!moved)return;moved=true;if(!ghost){ghost=document.createElement('div');ghost.className='drag-ghost';ghost.textContent={led:'LED + −',resistor:'220 Ω',button:'BUTON'}[kind];document.body.append(ghost);}ghost.style.left=(ev.clientX+12)+'px';ghost.style.top=(ev.clientY-24)+'px';ev.preventDefault();};const end=ev=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',end);document.removeEventListener('pointercancel',cancel);ghost?.remove();if(!moved)return;const svg=$('#bench');const rect=svg?.getBoundingClientRect();if(rect&&ev.clientX>=rect.left&&ev.clientX<=rect.right&&ev.clientY>=rect.top&&ev.clientY<=rect.bottom){const sx=(ev.clientX-rect.left)/rect.width*920,sy=(ev.clientY-rect.top)/rect.height*405;if(sx>=330&&sx<=880&&sy>=146&&sy<=320){const col=Math.round((sx-350)/34);const row=sy<233?Math.round((sy-158)/14):5+Math.round((sy-253)/14);place(kind,col,row);}else toast('Parçayı breadboard deliklerinin üzerine bırak.');}else toast('Parçayı çalışma masasının üzerine bırak.');};const cancel=()=>{ghost?.remove();document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',end);document.removeEventListener('pointercancel',cancel);};document.addEventListener('pointermove',move,{passive:false});document.addEventListener('pointerup',end,{once:true});document.addEventListener('pointercancel',cancel,{once:true});});}
function bind(){document.querySelectorAll('[data-home]').forEach(b=>b.onclick=e=>{e.preventDefault();navigate('home');});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson));document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.choice);render();});$('#hint')?.addEventListener('click',()=>{hint=!hint;$('#hint-text').hidden=!hint;$('#hint').setAttribute('aria-expanded',String(hint));$('#hint').textContent='Küçük bir ipucu '+(hint?'−':'+');});$('#check-answer')?.addEventListener('click',()=>{if(checked){finish();return;}if(selected===lesson.answer){checked=true;render();announce('Doğru. '+lesson.explanation);}else{const f=$('#feedback');f.className='feedback bad';f.textContent='Henüz değil. '+lesson.hint+' Başka bir yanıt deneyebilirsin.';}});
 document.querySelectorAll('[data-add]').forEach(b=>{drag(b,b.dataset.add);b.onclick=e=>{if(running){toast('Önce devreyi durdur.');return;}chosenPart=chosenPart===b.dataset.add?null:b.dataset.add;selectedPin=null;render();if(chosenPart&&e.detail===0)$(`[data-hole="${cursor}"]`)?.focus();};});document.querySelectorAll('[data-part]').forEach(el=>{drag(el,el.dataset.part);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();if(running){if(el.dataset.part==='button'&&!e.repeat)setPressed(true);return;}chosenPart=el.dataset.part;render();$(`[data-hole="${cursor}"]`)?.focus();announce('Parçayı taşımak için bir breadboard deliği seç.');}});});document.querySelectorAll('[data-pin]').forEach(el=>{el.addEventListener('click',()=>connect(el));el.addEventListener('focus',()=>{if(el.dataset.hole)cursor=el.dataset.hole;});el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();connect(el);return;}const d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(!d||!el.dataset.hole)return;e.preventDefault();const [c,r]=el.dataset.hole.split(',').map(Number);const n=$(`[data-hole="${Math.max(0,Math.min(15,c+d[0]))},${Math.max(0,Math.min(9,r+d[1]))}"]`);el.setAttribute('tabindex','-1');n.setAttribute('tabindex','0');n.focus();});});document.querySelectorAll('[data-wire]').forEach(el=>el.addEventListener('click',()=>{lab.wires.splice(Number(el.dataset.wire),1);invalidate();render();}));$('#reverse-led')?.addEventListener('click',()=>{const l=lab.parts.find(p=>p.kind==='led');if(l)l.reversed=!l.reversed;invalidate();render();});$('#clear-lab')?.addEventListener('click',()=>{lab={parts:[],wires:[]};chosenPart=null;invalidate();render();});$('#delay')?.addEventListener('input',e=>{delay=Number(e.target.value);labPassed=false;started=performance.now();$('#delay-value').textContent=delay+' ms';$('#frequency').textContent=(1000/(delay*2)).toFixed(2)+' döngü/sn';$('#sketch').textContent=makeSketch(lesson.mode,delay,pullup);if($('#finish-lab'))$('#finish-lab').disabled=true;if($('#lab-feedback'))$('#lab-feedback').textContent='Yeni ritmi gözlemle.';});$('#download-code')?.addEventListener('click',()=>download(lesson.mode==='button'?'pin_by_pin_button.ino':'pin_by_pin_led.ino',makeSketch(lesson.mode,delay,pullup),'text/plain;charset=utf-8'));$('#run-lab')?.addEventListener('click',()=>{if(running){running=false;pressed=false;render();return;}const state=circuitState(lab),b=lesson.mode==='button'?buttonState(lab,pullup):null;const bad=!state.ok?state:b&&!b.ok?b:null;if(bad){$('#lab-state').textContent=bad.message;$('#lab-state').dataset.ok='false';announce(bad.message);return;}running=true;started=performance.now();pressCycle=0;serialLines=[];render();$('#lab-state').textContent=b?b.message:state.message+' Yaklaşık 5,9 mA (LED açıkken).';$('#lab-state').dataset.ok='true';});$('#finish-lab')?.addEventListener('click',()=>{if(lesson.type==='bounce'?bs.streak>=3:lesson.type==='nowait'?nwPassed():labPassed&&running&&circuitState(lab).ok&&(lesson.mode!=='challenge'||delay===250))finish();});bindSims();
 $('#export-progress')?.addEventListener('click',()=>download('pin-by-pin-defterim.json',JSON.stringify(p,null,2),'application/json'));$('#import-progress')?.addEventListener('click',()=>$('#progress-file').click());$('#progress-file')?.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw new Error();const value=JSON.parse(await f.text());if(value.version!==1||!Array.isArray(value.completed)||!Array.isArray(value.dates))throw new Error();const imported=sanitizeProgress(value);p=sanitizeProgress({completed:[...p.completed,...imported.completed],dates:[...p.dates,...imported.dates]});save();render();toast('Defterin mevcut ilerlemene eklendi.');}catch{toast('Bu dosya geçerli bir Pin by Pin Lab defteri değil.');}});$('#reset-progress')?.addEventListener('click',()=>{if(confirm('Bu tarayıcıdaki ilerlemen sıfırlanacak. Devam etmek istiyor musun?')){p=sanitizeProgress({});save();render();}});
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(chosenPart||selectedPin)){chosenPart=null;selectedPin=null;render();}});
function tick(now){if(running){const ok=circuitState(lab).ok;let on;if(lesson.mode==='button'){if(now-lastSerial>=100){lastSerial=now;const lv=inputLevel(lab,{pressed,pullup});reading=lv==='FLOAT'?(Math.random()<.5?0:1):lv==='LOW'?0:1;serialLines=[...serialLines,reading].slice(-7);const s=$('#serial');if(s)s.textContent=serialLines.join('\n');}on=ok&&reading===0;}else on=ok&&(lesson.mode==='steady'||Math.floor((now-started)/delay)%2===0);$('#led-bulb')?.setAttribute('fill',on?'#ff8348':'#a35640');$('#led-glow')?.setAttribute('opacity',on?'.17':'0');
 if(view==='lesson'&&ok){if(lesson.mode==='button')labFeedback(pullup&&pressCycle===2,!pullup?'Pin boşta: basmadığında okumalar zıplıyor. pinMode’u INPUT_PULLUP yap.':pressCycle===0?'Devren çalışıyor. Şimdi butona bas ve basılı tut.':'Basılı: pin LOW (0), LED yanıyor. Şimdi bırak.',pullup?'':'bad');else if(now-started>Math.max(1200,delay*4))labFeedback(lesson.mode!=='challenge'||delay===250,'Devren çalışıyor. Şimdi ritmi ayarla: hedef bir saniyede iki tam döngü.');}}
 if(view==='lesson'&&lesson.type==='nowait')nowaitTick(now);requestAnimationFrame(tick);}
const labNo=()=>String(lessons.slice(0,lessons.indexOf(lesson)+1).filter(l=>l.type!=='quiz').length).padStart(2,'0');
function pushButton(part){const [xa,yt]=xy(part.col,4),[xb,yb]=xy(part.col+2,5),cx=(xa+xb)/2,cy=(yt+yb)/2;const inner=part.rotated?`M${xa} ${yt+8}H${xb}M${xa} ${yb-8}H${xb}`:`M${xa} ${yt+8}V${yb-8}M${xb} ${yt+8}V${yb-8}`;return `<g class="part-placed" data-part="button" id="push-button" tabindex="0" role="button" aria-label="Buton${part.rotated?', yan dönmüş':''}. Sürükleyerek taşı; devre çalışırken basmak için basılı tut."><path pointer-events="none" d="M${xa} ${yt}v6M${xb} ${yt}v6M${xa} ${yb}v-6M${xb} ${yb}v-6" stroke="#8b9381" stroke-width="2"/><rect x="${xa-9}" y="${yt+5}" width="${xb-xa+18}" height="${yb-yt-10}" rx="4" fill="#2f3d38" stroke="#1d2925"/><path pointer-events="none" d="${inner}" stroke="#8fa298" stroke-width="1.5" stroke-dasharray="3 3"/><circle id="button-cap" cx="${cx}" cy="${cy}" r="10" fill="${pressed?'#e5f292':'#55695f'}" stroke="#1d2925"/></g>`;}
function buttonControls(){return `<label for="pin-mode">pinMode(BUTTON_PIN, …)</label><select id="pin-mode" class="select"><option value="pullup" ${pullup?'selected':''}>INPUT_PULLUP</option><option value="input" ${pullup?'':'selected'}>INPUT (pull-up yok)</option></select><button class="press" id="press" ${running?'':'disabled'} aria-pressed="${pressed}">Butona bas · basılı tut</button><div class="code-label" style="margin-top:16px">SERIAL MONITOR · 115200</div><pre class="serial" id="serial" aria-label="Serial Monitor çıktısı">${serialLines.join('\n')}</pre>`;}
function setPressed(v){if(!running||lesson?.mode!=='button'||pressed===v)return;pressed=v;if(v&&pressCycle===0)pressCycle=1;if(!v&&pressCycle===1)pressCycle=2;$('#button-cap')?.setAttribute('fill',v?'#e5f292':'#55695f');$('#press')?.classList.toggle('down',v);$('#press')?.setAttribute('aria-pressed',String(v));}
function labFeedback(valid,todo,tone='bad'){labPassed=valid;const b=$('#finish-lab');if(b)b.disabled=!valid;const f=$('#lab-feedback');if(!f)return;const text=valid?'Devren çalışıyor ve görevin hedefini karşılıyor.':todo;if(f.textContent!==text){f.className='feedback '+(valid?'good':tone);f.textContent=text;}}
function bounceText(){return !bs.signal?'Henüz basmadın.':bs.count===1?`Bu basış tam bir kez sayıldı. Üst üste: ${bs.streak} / 3`:`Tek basış ${bs.count} kez sayıldı. Zıplamalar yeni basış gibi görünüyor.`;}
function bounceScope(){const s=bs.signal,W=600,H=150,hi=38,lo=112;const labels=`<text x="12" y="${hi-14}" class="scope-label">HIGH · 1</text><text x="12" y="${lo+24}" class="scope-label">LOW · 0</text>`;if(!s)return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Sinyal ekranı, henüz basış yok"><path d="M0 ${hi}H${W}" class="trace"/>${labels}<text x="${W/2}" y="${(hi+lo)/2+4}" text-anchor="middle" class="scope-hint">Butona bas: GPIO 22’deki sinyal burada görünür.</text></svg>`;
 const k=W/s.length,acc=debounce(s,bs.ms);const d=s.map((v,t)=>`${t?'L':'M'}${(t*k).toFixed(1)} ${v?hi:lo}H${((t+1)*k).toFixed(1)}`).join('');
 return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Sinyal ekranı: bu basış ${bs.count} kez sayıldı">${acc.map(([t])=>`<rect x="${(t*k).toFixed(1)}" y="16" width="${Math.max(1.5,bs.ms*k).toFixed(1)}" height="${H-32}" class="window"/>`).join('')}<path d="${d}" class="trace"/>${acc.filter(([,v])=>v===0).map(([t])=>`<circle cx="${(t*k).toFixed(1)}" cy="${lo}" r="5" class="count-dot"/>`).join('')}${labels}<text x="${W-12}" y="${hi-14}" text-anchor="end" class="scope-label">0–${s.length} ms · ● sayılan basış</text></svg>`;}
function bouncePage(){const done=bs.streak>=3;return `<section class="exercise"><div class="workbench-top"><div class="eyebrow">DENEY / ${labNo()}</div><span class="model-tag">ZIPLAMA MODELİ · MS BAŞINA 1 OKUMA</span></div><div class="scope" id="scope">${bounceScope()}</div><div class="lab-lower"><div><div class="code-label">SKETCH.INO · DEBOUNCE</div><pre><code id="sketch">${esc(makeDebounceSketch(bs.ms))}</code></pre></div><div><div class="code-label">BAS VE SAY</div><div class="lab-control"><label for="debounce">Bir değişimden sonra yok sayma süresi</label><input id="debounce" type="range" min="0" max="100" step="5" value="${bs.ms}"><div class="range-readout"><span id="debounce-value">${bs.ms} ms</span><span>açık alan: yok sayılan süre</span></div><button class="primary" id="bounce-press">Butona bir kez bas</button><div class="lab-state" id="bounce-state" role="status">${bounceText()}</div></div><p class="model-note">Her basış farklı zıplar. Model sinyali milisaniyede bir okur ve videodaki koşulu uygular: değer değiştiyse ve son kabulden beri yeterli süre geçtiyse kabul et.</p></div></div><div class="feedback ${done?'good':''}" id="lab-feedback" role="status">${done?'Üç basış üst üste tam birer kez sayıldı.':''}</div><div class="exercise-bottom"><small>Üst üste üç basış, her biri tam bir kez sayılsın.</small><button class="primary" id="finish-lab" ${done?'':'disabled'}>Görevi tamamla ↗</button></div></section>`;}
const nwPassed=()=>nw.mode==='millis'&&nw.streak>=3&&nw.triedDelay>0;
function nowaitStats(){const c=nw.presses.filter(p=>p.ok).length;return `Yakalanan <b>${c}</b> · Kaçırılan <b>${nw.presses.length-c}</b>${nw.mode==='millis'?` · Üst üste <b>${Math.min(nw.streak,3)}</b> / 3`:''}`;}
function nowaitPage(){const d=nw.mode==='delay';return `<section class="exercise"><div class="workbench-top"><div class="eyebrow">DENEY / ${labNo()}</div><span class="model-tag">ZAMANLAMA MODELİ</span></div><div class="segmented" role="group" aria-label="Kod sürümü">${['delay','millis'].map(m=>`<button data-version="${m}" class="${nw.mode===m?'active':''}" aria-pressed="${nw.mode===m}">${m}() sürümü</button>`).join('')}</div><div class="nowait-stage"><svg class="nowait-leds" viewBox="0 0 230 112" role="img" aria-label="Kırmızı LED GPIO 23’te, yeşil LED GPIO 25’te">${['red','green'].map((c,i)=>`<g transform="translate(${30+i*120} 8)"><path id="nw-${c}" d="M10 64V30a20 20 0 0 1 40 0v34z" fill="${c==='red'?'#a35640':'#4f6a4a'}" stroke="#2b3a34" stroke-width="1.5"/><path d="M4 64h52" stroke="#2b3a34" stroke-width="3"/><text x="30" y="92" text-anchor="middle" class="scope-label">${c==='red'?'GPIO 23 · 500 ms':d?'GPIO 25 · sıra yok':'GPIO 25 · 150 ms'}</text></g>`).join('')}</svg><button class="press" id="nw-press">Butona bas</button></div><div class="code-label" style="margin-top:20px">SON 3 SANİYE · ÇİZGİLER: KODUN BUTONU OKUDUĞU ANLAR</div><div class="timeline" id="timeline"></div><div class="nw-stats" id="nw-stats">${nowaitStats()}</div><div class="lab-lower"><div><div class="code-label">SKETCH.INO · ${d?'DELAY() İLE':'MILLIS() İLE'}</div><pre><code>${esc(makeTimerSketch(nw.mode))}</code></pre></div><div><div class="code-label">NE OLUYOR?</div><div class="lab-control"><p class="nw-explain">${d?'loop() her turda 500 ms bekler. Buton yalnızca beklemelerin arasında, yarım saniyede bir okunur. Kısa bir basış çoğu zaman araya düşer ve kaçar. İkinci bir LED için de sıra gelmez.':'loop() hiç beklemez, her turda saate bakar. Buton saniyede binlerce kez okunur ve her basış hemen yakalanır. Yeşil LED de kendi hızında yanıp söner.'}</p></div></div></div><div class="feedback ${nwPassed()?'good':''}" id="lab-feedback" role="status"></div><div class="exercise-bottom"><small>millis() sürümünde üst üste üç basış yakala.</small><button class="primary" id="finish-lab" ${nwPassed()?'':'disabled'}>Görevi tamamla ↗</button></div></section>`;}
function timeline(t){const W=600,span=3000,x=ms=>(ms-(t-span))/span*W;const reads=nw.mode==='delay'?Array.from({length:7},(_,i)=>(Math.floor(t/500)-i)*500).filter(r=>r>=0&&r>=t-span).map(r=>`<path d="M${x(r).toFixed(1)} 6V54" class="read"/>`).join(''):`<rect x="0" y="6" width="${W}" height="48" class="read-band"/>`;const bars=[...nw.presses,...(nw.downAt!==null?[{down:nw.downAt,up:t,live:true}]:[])].filter(p=>p.up>=t-span).map(p=>{const a=Math.max(0,x(p.down));return `<rect x="${a.toFixed(1)}" y="20" width="${Math.max(3,x(p.up)-a).toFixed(1)}" height="20" rx="3" class="${p.live?'held':p.ok?'hit':'miss'}"/>`;}).join('');return `<svg viewBox="0 0 ${W} 60" preserveAspectRatio="none" aria-hidden="true">${reads}${bars}</svg>`;}
function nowaitTick(now){const t=now-nw.t0;$('#nw-red')?.setAttribute('fill',nw.blinking&&Math.floor(t/500)%2===0?'#ff8348':'#a35640');$('#nw-green')?.setAttribute('fill',nw.mode==='millis'&&Math.floor(t/150)%2===0?'#a6e26f':'#4f6a4a');const tl=$('#timeline');if(tl)tl.innerHTML=timeline(t);}
function nwDown(){if(nw.downAt!==null)return;nw.downAt=performance.now()-nw.t0;if(nw.mode==='millis')nw.blinking=!nw.blinking;$('#nw-press')?.classList.add('down');}
function nwUp(){if(nw.downAt===null)return;const p={down:nw.downAt,up:performance.now()-nw.t0};nw.downAt=null;p.ok=caught(p,nw.mode);if(nw.mode==='delay'){nw.triedDelay++;if(p.ok)nw.blinking=!nw.blinking;}else nw.streak=p.ok?nw.streak+1:0;nw.presses=[...nw.presses,p].slice(-12);$('#nw-press')?.classList.remove('down');$('#nw-stats').innerHTML=nowaitStats();const done=nwPassed();$('#finish-lab').disabled=!done;const f=$('#lab-feedback');f.className='feedback '+(done?'good':p.ok?'':'bad');f.textContent=nw.mode==='delay'?(p.ok?'Bu basış bir okuma anına denk geldi ve yakalandı. Şans eseri.':'Kaçtı: basışın iki okuma anının arasında kaldı. ESP32 o sırada delay() içinde bekliyordu.'):done?'Üç basış üst üste yakalandı. LED’ler beklemeden çalışırken buton da dinlendi.':!nw.triedDelay?'Yakalandı. Farkı görmek için delay() sürümünü de dene.':`Yakalandı: ${Math.min(nw.streak,3)} / 3.`;}
function bindSims(){
 $('#rotate-button')?.addEventListener('click',()=>{const b=lab.parts.find(p=>p.kind==='button');if(b)b.rotated=!b.rotated;invalidate();render();});
 $('#pin-mode')?.addEventListener('change',e=>{pullup=e.target.value==='pullup';pressCycle=0;labPassed=false;$('#sketch').textContent=makeSketch(lesson.mode,delay,pullup);if(running)$('#lab-state').textContent=buttonState(lab,pullup).message;});
 const hold=(el,down,up)=>{if(!el)return;el.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();down();});for(const ev of ['pointerup','pointerleave','pointercancel'])el.addEventListener(ev,up);el.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();if(!e.repeat)down();}});el.addEventListener('keyup',e=>{if(e.key===' '||e.key==='Enter')up();});};
 hold($('#press'),()=>setPressed(true),()=>setPressed(false));hold($('#nw-press'),nwDown,nwUp);
 const pb=$('#push-button');if(pb){pb.addEventListener('pointerdown',e=>{if(!running)return;e.preventDefault();setPressed(true);document.addEventListener('pointerup',()=>setPressed(false),{once:true});});pb.addEventListener('keyup',e=>{if(e.key===' '||e.key==='Enter')setPressed(false);});}
 $('#bounce-press')?.addEventListener('click',()=>{bs.signal=bounceSignal(1+Math.floor(Math.random()*1e6));bs.count=countPresses(bs.signal,bs.ms);bs.streak=bs.count===1?bs.streak+1:0;render();announce(bounceText());});
 $('#debounce')?.addEventListener('input',e=>{bs.ms=Number(e.target.value);bs.streak=0;if(bs.signal)bs.count=countPresses(bs.signal,bs.ms);$('#debounce-value').textContent=bs.ms+' ms';$('#scope').innerHTML=bounceScope();$('#sketch').textContent=makeDebounceSketch(bs.ms);$('#bounce-state').textContent=bounceText();$('#finish-lab').disabled=true;$('#lab-feedback').className='feedback';$('#lab-feedback').textContent='';});
 document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{nw={...nw,mode:b.dataset.version,t0:performance.now(),presses:[],streak:0,blinking:true,downAt:null};render();});
}
window.addEventListener('hashchange',route);route();requestAnimationFrame(tick);
